const ic = (n, c = '') => `<svg class="ic ${c}" viewBox="0 0 24 24" aria-hidden="true">${ICONS[n] || ''}</svg>`;
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;');
const go = (to, extra = '') => `data-go="${to}" ${extra}`;

/* ---------- khối dùng chung ---------- */
const logo = `<span class="logo">${ic('shield-check')}</span>`;
function topbar(o = {}) {
  const b = o.badge ? `<span class="badge">${o.badge}</span>` : '';
  return `<header class="topbar"><div class="brand">${logo}<div class="grow"><strong class="ellipsis">Bản đồ CSKV</strong><small class="ellipsis">Công an tỉnh Lâm Đồng</small></div></div>
  <div class="actions">
    <button class="topbar-btn" ${go('c11')}>${ic('message-square-text')}<span>Trợ lý</span></button>
    <button class="topbar-btn" ${go('c09')}>${ic('bell')}<span>Thông báo</span>${b}</button>
    <button class="topbar-btn" ${go('c12')}>${ic('menu')}<span>Tính năng</span></button>
  </div></header>`;
}
function tabbar(active) {
  const t = [['map', 'Bản đồ', 'c03', 'map'], ['dir', 'Danh bạ', 'c04', 'contact-round'], ['rep', 'Phản ánh', 'c06', 'file-text'], ['acc', 'Tài khoản', 'c10', 'user-round']];
  return `<nav class="tabbar" aria-label="Điều hướng chính">${t.map(([k, l, to, i]) => `<button class="tabbar-item ${active === k ? 'is-active' : ''}" ${go(to)}>${ic(i)}<span>${l}</span></button>`).join('')}</nav>`;
}
const phone = (inner, o = {}) => `<div class="phone ${o.cls || ''}">${o.head === false ? '' : topbar(o)}<div class="body">${inner}</div>${o.tab ? tabbar(o.tab) : ''}${o.overlay || ''}</div>`;
const phoneBare = (inner, o = {}) => `<div class="phone ${o.cls || ''}"><div class="body">${inner}</div>${o.tab ? tabbar(o.tab) : ''}</div>`;
const desk = (inner) => `<div class="desk">${inner}</div>`;
const pagehead = (title, sub, back) => `<div class="pagehead">${back ? `<button class="back" ${go(back)}>${ic('arrow-left', 'sm')}Quay lại</button>` : ''}<h1 class="t-h1">${title}</h1>${sub ? `<p class="muted t-sm" style="margin-top:var(--space-1)">${sub}</p>` : ''}</div>`;
const field = (label, control, hint, err) => `<div class="field"><label>${label}</label>${control}${err ? `<span class="err">${ic('circle-alert', 'sm')}${err}</span>` : hint ? `<span class="hint">${hint}</span>` : ''}</div>`;
const input = (ph, v = '', cls = '', type = 'text') => `<input class="input ${cls}" type="${type}" placeholder="${ph}" value="${v}"/>`;
const status = (tone, text) => `<span class="status ${tone}">${text}</span>`;
const alert = (tone, title, text) => `<div class="alert ${tone}" role="${tone === 'err' ? 'alert' : 'status'}">${ic(tone === 'ok' ? 'circle-check' : tone === 'err' ? 'circle-alert' : tone === 'warn' ? 'triangle-alert' : 'info')}<div><strong>${title}</strong>${text ? `<p>${text}</p>` : ''}</div></div>`;
const state = (icon, title, text, action, tone = '') => `<div class="state"><span class="tile ${tone}">${ic(icon, 'lg')}</span><h3>${title}</h3><p>${text}</p>${action || ''}</div>`;
const loading = (text) => `<div class="state"><span class="spinner" role="status" aria-label="Đang tải"></span><p>${text}</p></div>`;
const skeletonRows = (n = 4) => `<div class="list">${Array.from({ length: n }, () => `<div class="list-item"><span class="tile"></span><div class="grow col" style="gap:var(--space-1)"><span class="skeleton" style="width:70%"></span><span class="skeleton" style="width:40%"></span></div></div>`).join('')}</div>`;

/* bản đồ minh hoạ: ranh giới, đường, ghim */
function mapArt(o = {}) {
  const pins = (o.pins || []).map(([x, y, k]) => `<span class="pin ${k || ''}" style="left:${x}%;top:${y}%">${ic(k === 'alert' ? 'triangle-alert' : 'map-pin', 'lg')}</span>`).join('');
  const me = o.me ? `<span class="me" style="left:${o.me[0]}%;top:${o.me[1]}%"></span>` : '';
  return `<div class="map ${o.cls || ''}" style="${o.style || 'position:absolute;inset:0'}"><svg class="land" viewBox="0 0 390 700" preserveAspectRatio="xMidYMid slice" aria-hidden="true">
    <polygon points="20,120 190,60 330,130 360,300 250,380 90,340" fill="var(--color-success-soft)" stroke="var(--color-map)" stroke-width="2" stroke-dasharray="6 5"/>
    <polygon points="190,380 360,300 370,520 220,620 120,520" fill="var(--color-warning-soft)" stroke="var(--color-map)" stroke-width="2" stroke-dasharray="6 5"/>
    ${o.sel ? '<polygon points="110,250 250,270 240,360 130,380 70,320" fill="var(--color-primary-soft)" stroke="var(--color-primary)" stroke-width="3"/>' : ''}
    <path d="M0,260 C100,230 200,300 390,240" stroke="var(--color-surface)" stroke-width="9" fill="none"/><path d="M200,0 C210,200 150,400 230,700" stroke="var(--color-surface)" stroke-width="7" fill="none"/>
  </svg>${pins}${me}</div>`;
}
const searchBox = (v = '', ph = 'Tìm xã/phường hoặc mã địa bàn…') => `<div class="input-wrap has-lead">${`<span class="lead">${ic('search')}</span>`}<input class="input" placeholder="${ph}" value="${v}"/>${v ? `<button class="adorn" aria-label="Bỏ chọn địa bàn, xem toàn tỉnh">${ic('x')}</button>` : `<button class="adorn" aria-label="Mở danh bạ địa bàn" ${go('c04')}>${ic('contact-round')}</button>`}</div>`;
